mapper.select:
SELECT COUNT(1)
FROM visual_screen.vs_lib_index_scheme s
WHERE 1 = 1

    AND s.scheme_descr LIKE CONCAT(CONCAT('%', #{params.schemeDescr}), '%')


    AND LEFT(s.add_date, 10) >= #{params.begin_time}


    AND LEFT(s.add_date, 10) <= #{params.end_time}

SELECT s.id AS "ID", s.scheme_descr AS "SCHEME_DESCR", s.scheme_conditon AS "SCHEME_CONDITON", visual_screen.f_get_IndexName(s.scheme_colums) AS "INDEX_NAME", s.add_date AS "ADD_DATE", su.realname AS "realname" FROM visual_screen.vs_lib_index_scheme s LEFT JOIN visual_screen.sys_user su ON s.add_userid = su.id WHERE 1 = 1
AND s.scheme_descr LIKE CONCAT(CONCAT('%', #{params.schemeDescr}), '%')
AND LEFT(s.add_date, 10) >= #{params.begin_time}
AND LEFT(s.add_date, 10) <= #{params.end_time}
ORDER BY s.add_date DESC NULLS LAST LIMIT #{params.pageSize,jdbcType=INTEGER} OFFSET #{params.page,jdbcType=INTEGER}
